const PDFS = ["fresher-btech", "experienced-dev", "two-column", "caps-headings"];
const DOCXS = ["fresher-word", "experienced-word"];

// Personal data from "Personal Details", "Declaration" and similar sections that must never be imported.
const FORBIDDEN = [
  /Rajesh/,
  /2001-08/,
  /14\/08/,
  /declare/i,
  /Married/,
  /Gender/,
  /Single/,
  /Hindi/,
  /Cricket/,
  /Painting/,
  /1990/,
];

function expectDraft(draft, expected) {
  const { experience, education, skills, projects, certifications, links, ...fields } = expected;
  expect(draft).toMatchObject(fields);
  if (links) expect(draft.links).toMatchObject(links);
  expect((draft.experience ?? []).map((job) => [job.title, job.company, job.startDate])).toEqual(
    experience,
  );
  expect(
    (draft.education ?? []).map((school) => [school.institution, school.level, school.degree]),
  ).toEqual(education);
  expect(draft.skills).toHaveLength(skills);
  expect((draft.projects ?? []).map((project) => project.name)).toEqual(projects);
  expect((draft.certifications ?? []).map((cert) => cert.name)).toEqual(certifications);
  for (const pattern of FORBIDDEN) expect(JSON.stringify(draft)).not.toMatch(pattern);
}

describe("buildDraft on saved step-1 output (no file parsing)", () => {
  it.each(PDFS)("%s.pdf", async (name) => {
    const { lines, twoColumns } = groupLines(await readJson(`${name}.items.json`));
    expectDraft(buildDraft(lines, { twoColumns }).draft, EXPECTED[name]);
  });

  it.each(DOCXS)("%s.docx", async (name) => {
    const lines = await readJson(`${name}.lines.json`);
    expectDraft(buildDraft(lines).draft, EXPECTED[name]);
  });
});

describe("parseCv on the real files", () => {
  it.each([
    ...PDFS.map((name) => [`${name}.pdf`, CV_MIME_TYPES.pdf, name]),
    ...DOCXS.map((name) => [`${name}.docx`, CV_MIME_TYPES.docx, name]),
  ])("%s", async (file, mimeType, name) => {
    const { draft } = await parseCv({ buffer: await readFile(fixture(file)), mimeType });
    expectDraft(draft, EXPECTED[name]);
  });

  it("warns about two columns", async () => {
    const buffer = await readFile(fixture("two-column.pdf"));
    const { warnings } = await parseCv({ buffer, mimeType: CV_MIME_TYPES.pdf });
    expect(warnings).toContain(CV_PARSER_MESSAGES.twoColumns);
  });

  it.each([
    ["a PDF without text (scanned)", () => readFile(fixture("no-text.pdf")), CV_MIME_TYPES.pdf],
    ["a broken PDF", async () => Buffer.from("%PDF-1.7 not really"), CV_MIME_TYPES.pdf],
    ["a broken DOCX", async () => Buffer.from("not a zip"), CV_MIME_TYPES.docx],
  ])("rejects %s with a friendly 400", async (_label, load, mimeType) => {
    await expect(parseCv({ buffer: await load(), mimeType })).rejects.toMatchObject({
      code: "VALIDATION_ERROR",
      message: CV_PARSER_MESSAGES.unreadable,
    });
  });

  it("rejects other file types", async () => {
    await expect(
      parseCv({ buffer: Buffer.from("hi"), mimeType: "text/plain" }),
    ).rejects.toMatchObject({
      code: "UNSUPPORTED_FILE_TYPE",
    });
  });
});

describe("buildDraft warnings and validation", () => {
  const line = (text, options = {}) => makeLine({ text, ...options });

  it("drops undated jobs and unreadable entries with warnings, and warns when there's no email", () => {
    const { draft, warnings } = buildDraft([
      line("Asha Rao", { bold: true }),
      line("Experience", { bold: true }),
      line("Developer | Acme Solutions", { bold: true }),
      line("• Built things"),
      line("Education", { bold: true }),
      line("Some Course, 2019 – 2020"),
      line("VOLUNTEERING", { bold: true }),
      line("Won a hackathon"),
    ]);
    expect(draft).toEqual({ fullName: "Asha Rao" });
    expect(warnings).toEqual([
      CV_PARSER_MESSAGES.unknownSection("VOLUNTEERING"),
      CV_PARSER_MESSAGES.noDates(1),
      CV_PARSER_MESSAGES.skippedEntries(1, "education"),
      CV_PARSER_MESSAGES.noEmail,
    ]);
  });

  it("never imports an ignored section, even one full of contact-like data", () => {
    const { draft } = buildDraft([
      line("Asha Rao", { bold: true }),
      line("Personal Details", { bold: true }),
      line("Email: father@example.com"),
      line("Phone: 98765 43210"),
      line("Date of Birth: 01/01/2000"),
    ]);
    expect(draft).toEqual({ fullName: "Asha Rao" });
  });
});
